def render(page=0):
 page=max(0,min(int(page),len(PAGES)-1)); title,body=PAGES[page]
 rows=[]
 if page>0: rows.append(Button.inline("⬅️ قبلی",PREFIX+f"page:{page-1}".encode()))
 if page<len(PAGES)-1: rows.append(Button.inline("➡️ بعدی",PREFIX+f"page:{page+1}".encode()))
 nav=[Button.inline("📚 فهرست راهنما",PREFIX+b"index"),Button.inline("🏠 پنل مدیریت",b"rep:home")]
 return f"📘 **راهنمای حرفه‌ای مدیریت ربات**\n\n{title}\n\n{body}\n\n📖 صفحه {page+1} از {len(PAGES)}", ([rows] if rows else [])+[nav]

def index():
 rows=[]
 for i in range(0,len(PAGES),2):
  row=[Button.inline(f"{i+1}. {PAGES[i][0]}",PREFIX+f"page:{i}".encode())]
  if i+1<len(PAGES): row.append(Button.inline(f"{i+2}. {PAGES[i+1][0]}",PREFIX+f"page:{i+1}".encode()))
  rows.append(row)
 rows.append([Button.inline("🏠 پنل مدیریت",b"rep:home")])
 return "📚 **فهرست راهنمای مدیریت**\n\nموضوع موردنظر را انتخاب کنید:",rows

async def callback_handler(event):
 data=event.data
 if not data.startswith(PREFIX): return False
 action=data[len(PREFIX):].decode(errors="ignore")
 if action=="index": text,buttons=index()
 elif action.startswith("page:"):
  try: page=int(action.split(":",1)[1])
  except (ValueError,TypeError): page=0
  text,buttons=render(page)
 else: return False
 await event.edit(text,buttons=buttons); await event.answer(); return True
